class Solution {
public:
    bool mirror(string& w) {
        int l = 0, r = w.size() - 1;
        while (l < r) {
            if (w[l] != w[r]) return false;
            l++;
            r--;
        }
        return true;
    }
    string firstPalindrome(vector<string>& words) {
        for (int k = 0; k < (int)words.size(); k++) {
            if (mirror(words[k])) return words[k];
        }
        return "";
    }
};
